// === Tab: mySketch ===
const string = "PIKNIC ELECTRONIK"; //words to be displayed
const size = 160; //font size
const fontFile = "https://deckard.openprocessing.org/user203215/visual807387/h9350396a80dfc6ef0eece5f146b6b8be/NBGrotesk-85R_Schwer.ttf";
const showText = true; //whether or not to have an overlay of the original text (in the background color)
const textAlpha = 1; //the alpha of the text if displayed (low value will make it slowly fade in)
const backgroundColor = 0; //kinda self-explanatory
const strokeAlpha = 60; //the alpha of the lines (lower numbers are more transparent)
const strokeColor = 240; //the line color

"use strict";
var song;
var analyzer;

function preload() {
    song = loadSound("https://deckard.openprocessing.org/user203215/visual807387/h9350396a80dfc6ef0eece5f146b6b8be/Floating_Points_-_KG_Beat.mp3");
		font = loadFont(fontFile);
}

const P = new p5.Shader(this._renderer,
    // vert
    `attribute vec3 aPosition;
varying vec2 vuv;

void main() {

gl_Position = vec4(vuv = 2. * aPosition.xy - 1., 0, 1);
}`,
    // frag
    `precision highp float;
varying vec2 vuv;
uniform float time, asp;
uniform sampler2D uSampler;

void main()
{
    if (abs(vuv.y) > .95) discard;

		float snd = texture2D(uSampler, vec2(0)).r;

		vec3 ro = vec3(4. * vec2(vuv.x * asp, vuv.y), -1.);
    vec3 tro = ro;

		#define random(st)(fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * .5453123))
    tro.z *= ro.z * 5. + 2. / random(vec2(ro.x, ro.y)); 

		#define R(p, a) p = (cos(a) * p + sin(a) * vec2(p.y, -p.x))
		R(ro.xz, 2. * time);
    R(ro.yz, time);

    lowp vec3 col = vec3(0);
    col = vec3(.102, 0.201, 0.25) * reflect(-vec3(.5, 1, .5), min(vec3(length(max(snd * ro, 0.) - ro)) - 2., vec3(fract(tro * snd)))) + .02;

		gl_FragColor.rgb = col;
    gl_FragColor.a = 6.;
}`);

function setup() {
    createCanvas(windowWidth, windowHeight, WEBGL);

    song.loop();
    analyzer = new p5.Amplitude()
    analyzer.setInput(song);

    setAttributes({
        alpha: !1,
        depth: !1,
        stencil: !1,
        antialias: !1,
        premultipliedAlpha: !1,
        presereDrawingBuffer: !1,
        failIfMajorPerformanceCaveat: !1
    });

    background("#222222");
    shader(P);

    const wnin = Math.max(windowWidth, windowHeight);
    const wnax = Math.max(windowWidth, windowHeight);
    P.setUniform("asp", wnax * 1.0001 / wnin);

		textFont(font);
		textSize(size);
};

function draw() {

    const img = createImage(1, 1);
    img.loadPixels();
    img.pixels[0] = (analyzer.getLevel() * 254) | 0; //cast int
    img.pixels[3] = 255; //alpha
    img.updatePixels();

    P.setUniform("uSampler", img);
    P.setUniform("time", millis() * .001); //performance.now() 

    rect(0, 0, 0, 0);
};

